import test from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { analyzeShellCommand, checkCommitBranches, downgradeVerifiedCommit, explicitShellEffect, gitBranchAt,
  gitCommitPlan, installShellGuard, markers, scanShell, BRANCH_GATED_PATTERNS } from '../plugins/v2/shell-guard.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
// The live permissive rule set, generated by configure.py.
const RULES = JSON.parse(execFileSync('python3', ['-c',
  'import json,configure;print(json.dumps(configure.shell_rules("permissive"))); assert set(configure.BRANCH_GATED_ASK) == set(json.loads(input()))'],
  { cwd: root, encoding: 'utf8', input: JSON.stringify([...BRANCH_GATED_PATTERNS]) }));

// Real repositories: M on main, MA on master, F on a feature branch, D detached, N not a repository.
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'guard-commit-'));
const git = (cwd, ...args) => execFileSync('git', ['-c', 'user.name=t', '-c', 'user.email=t@t', ...args], { cwd, stdio: 'pipe' });
function repo(name, branch, detach = false) {
  const dir = path.join(tmp, name);
  fs.mkdirSync(dir);
  git(dir, 'init', '-q', '-b', branch);
  git(dir, 'commit', '-q', '--allow-empty', '-m', 'init');
  if (detach) git(dir, 'checkout', '-q', '--detach');
  return dir;
}
const M = repo('main-repo', 'main'), MA = repo('master-repo', 'master'), F = repo('feature-repo', 'feat/x'), D = repo('detached', 'main', true);
const N = path.join(tmp, 'plain'); fs.mkdirSync(N);
fs.mkdirSync(path.join(F, 'sub'));
test.after(() => fs.rmSync(tmp, { recursive: true, force: true }));

// Simulates one shell call through the plugin: the guard's execute.before, then the native assert over
// the parsed commands (approximated by scanner segments; cd becomes a directory check) with the
// agent's rules and the guard's evaluate hook. Returns 'allow' or 'ask'.
async function decide(command, base = F) {
  const hooks = {}, evaluateHooks = [];
  let guardAsked = false;
  const ctx = {
    location: { directory: base },
    tool: { hook: async (name, callback) => { hooks[name] = callback; } },
    agent: { list: async () => ({ data: [{ id: 'harness-builder', permissions: RULES }] }) },
    permission: {
      hook: async (name, callback) => { evaluateHooks.push(callback); },
      assert: async input => {
        const event = { ...input, effect: 'allow' };
        for (const hook of evaluateHooks) await hook(event);
        if (event.effect === 'ask') guardAsked = true;
      },
    },
  };
  await installShellGuard(ctx);
  const call = { tool: 'shell', sessionID: 'ses_t', agent: 'harness-builder', messageID: 'msg_t', id: `call_${Math.random()}` };
  try { await hooks['execute.before']({ ...call, input: { command } }); }
  catch { return 'deny'; }
  if (guardAsked) return 'ask';
  const resources = scanShell(command).segments.filter(segment => segment.hasCommand && segment.words[0] !== 'cd').map(segment => segment.text);
  if (!resources.length) return 'allow';
  const effect = resources.some(resource => explicitShellEffect(resource, RULES)?.effect !== 'allow') ? 'ask' : 'allow';
  const event = { action: 'shell', sessionID: call.sessionID, agent: call.agent, resources, source: { type: 'tool', messageID: call.messageID, id: call.id }, effect };
  for (const hook of evaluateHooks) await hook(event);
  return event.effect;
}

const HEREDOC = `git commit -m "$(cat <<'EOF'\nfix: handle (parens) and don't break\n\ncd somewhere is just text\nEOF\n)"`;

test('branch resolution reads the current branch and fails closed', async () => {
  assert.equal(await gitBranchAt(M), 'main');
  assert.equal(await gitBranchAt(MA), 'master');
  assert.equal(await gitBranchAt(F), 'feat/x');
  assert.equal(await gitBranchAt(path.join(F, 'sub')), 'feat/x');
  assert.equal(await gitBranchAt(D), undefined);
  assert.equal(await gitBranchAt(N), undefined);
  assert.equal(await gitBranchAt(path.join(tmp, 'missing')), undefined);
});

test('add and commit on a feature branch go through without an ask', async () => {
  const allowed = [
    ['git add -A', F], ['git add src/a.js src/b.js', F], ['git stage -u', F], ['git commit -m "feat: x"', F],
    ['git add . && git commit -m "fix: y"', F], [HEREDOC, F], [`git add -A && ${HEREDOC}`, F],
    ['git status && git add x && git commit -m y && git push -u origin HEAD', F],
    ['git commit -am "wip"', F], ['git commit --fixup=HEAD', F], ['git -c user.name=Z -c user.email=z@x commit -m x', F],
    ['git add -A && git commit -m x', path.join(F, 'sub')],
    [`cd ${F} && git add -A && git commit -m x`, M], [`cd ${F}/sub && git commit -m x`, M], [`cd ${M} && cd ../feature-repo && git commit -m x`, N],
    ['cd sub && git commit -m x', F], [`git -C ${F} commit -m x`, M], [`git -C ${tmp} -C feature-repo add .`, M],
    ['git log --oneline -3; git add a && git commit -m x', F],
    ['GIT_EDITOR=true git commit', F], ['git commit -m "update .gitignore"', F], ['git add .gitignore', F],
  ];
  for (const [command, base] of allowed) assert.equal(await decide(command, base), 'allow', `${command} @ ${base}`);
});

test('add and commit on main, master, detached or unknown HEAD ask', async () => {
  const asked = [
    ['git add -A', M], ['git commit -m x', M], ['git commit -m x', MA], ['git add . && git commit -m x', M], [HEREDOC, M],
    ['git commit -m x', D], ['git add x', N], ['git commit -m x', path.join(tmp, 'missing')],
    [`git -C ${M} commit -m x`, F], [`git -C ${M} add .`, F], [`cd ${M} && git commit -m x`, F], [`git -C ${tmp} -C main-repo add .`, F],
    [`git add -A && git -C ${M} commit -m x`, F], [`git commit -m a && cd ${M} && git commit -m b`, F],
    [`timeout 60 git -C ${M} commit -m x`, F], [`env A=1 git -C ${M} add .`, F], ['/usr/bin/git commit -m x', M],
  ];
  for (const [command, base] of asked) assert.equal(await decide(command, base), 'ask', `${command} @ ${base}`);
});

test('smuggling a branch or directory change asks even from a feature branch', async () => {
  const smuggled = [
    // Branch changes in the same command.
    ['git checkout main && git commit -m x', F], ['git switch main && git add . && git commit -m x', F],
    ['git checkout -b other && git commit -m x', F], ['git symbolic-ref HEAD refs/heads/main && git commit -m x', F],
    ['git branch -m main && git commit -m x', F], ['git branch -M feat/x main; git commit -m x', F],
    ['git worktree add ../w main && cd ../w && git commit -m x', F], ['gh pr checkout 12 && git commit -m x', F],
    ['git commit -m x; git checkout main', F],
    [`git -C ${M} checkout feat && git -C ${M} commit -m x`, F],
    // Writing HEAD or config directly.
    ['echo "ref: refs/heads/main" > .git/HEAD && git commit -m x', F], ['cp /tmp/h .git/HEAD; git commit -m x', F],
    ['git config core.worktree /x && git commit -m x', F], ['git config alias.ci commit && git ci -m x', F],
    // Repository redirection.
    [`GIT_DIR=${M}/.git git commit -m x`, F], [`export GIT_DIR=${M}/.git; git commit -m x`, F],
    [`GIT_WORK_TREE=${M} git add .`, F], [`git --git-dir=${M}/.git commit -m x`, F], [`git --work-tree=${M} add .`, F],
    ['git -c core.hooksPath=/tmp/h commit -m x', F], ['git -c alias.ci=commit ci -m x', F], ['git -c include.path=/tmp/c commit -m x', F],
    [`env -C ${M} git commit -m x`, F], [`env --chdir=${M} git add .`, F], [`git -C "$REPO" commit -m x`, F],
    // cd forms the guard cannot follow.
    [`cd ${F}; git commit -m x`, M], [`false || cd ${F} && git commit -m x`, M], [`true || cd ${F} && git commit -m x`, M],
    [`false && cd ${F}; git commit -m x`, M], [`(cd ${F} && true); git commit -m x`, M], [`(cd ${F}) && git commit -m x`, M],
    [`cd ${F} | true; git commit -m x`, M], [`cd ${F} & git commit -m x`, M], [`cd ${F}\ngit commit -m x`, M],
    [`cd ${F} && (git commit -m x)`, M], [`f() { cd ${F}; }; f; git commit -m x`, M], [`pushd ${F} && git commit -m x`, M],
    [`cd $HOME/feature && git commit -m x`, M], ['cd - && git commit -m x', M], [`CDPATH=${tmp} cd feature-repo && git commit -m x`, M],
    ['source ./env.sh && git commit -m x', F], [`if cd ${F}; then git commit -m x; fi`, M], [`builtin cd ${F} && git commit -m x`, M],
    // Wrappers that may run git elsewhere, and other ways to reach commit.
    ['sh -c "git commit -m x"', F], ['bash -c "git add ."', F], ['xargs -a f git -C x commit', F],
    [`find ${M} -maxdepth 0 -execdir git commit -m x \\;`, F], ['/usr/lib/git-core/git-commit -m x', F],
    ['echo $(git commit -m x)', M], ['timeout 60 git commit -m x', F], ['nohup git add . &', F],
  ];
  for (const [command, base] of smuggled) assert.equal(await decide(command, base), 'ask', `${command} @ ${base}`);
});

test('amend, branch deletes, force/delete pushes and other existing asks still ask on a feature branch', async () => {
  const still = ['git commit --amend --no-edit', 'git commit -m x --amend', 'git commit --amen', 'git commit --am -m y',
    `git -C ${F} commit --amend`, 'git add . && git commit --amend', 'git branch -d old', 'git branch -D old', 'git branch --delete old',
    'git branch --del old', 'git branch -dr origin/old', `git -C ${F} branch -D old`, 'timeout 5 git branch -d old',
    'git push --force origin feat/x', 'git push -f', 'git push --del origin old', 'git push --mirr', 'git push origin :old',
    'git reset --hard HEAD~1', `git -C ${F} reset --hard`, 'git rebase main', `git -C ${F} rebase -i HEAD~2`, 'git stash',
    `git -C ${F} stash`, 'git clean -fdx', 'git restore .', 'git checkout -- a.js', 'rm -rf build', 'sudo ls',
    'git add .env', 'git commit -m x .env', 'git add config/credentials.json', 'git add . && git commit -m "x" -- secrets/a'];
  for (const command of still) assert.equal(await decide(command, F), 'ask', command);
});

test('plain pushes and read-only git stay allowed', async () => {
  for (const command of ['git push', 'git push -u origin HEAD', 'git status', 'git log --grep commit -3', 'git diff --cached',
    `git -C ${M} log -1`, `git -C ${M} status`, 'git branch', 'git branch -a', 'git branch --show-current'])
    assert.equal(await decide(command, M), 'allow', command);
});

test('plan details: gated flags, cwd resolution and unknown reasons', () => {
  let plan = gitCommitPlan(`cd ${F} && git add . && git -C sub commit -m x`, M);
  assert.equal(plan.unknown, undefined);
  assert.deepEqual(plan.targets.map(t => [t.cwd, t.gated]), [[F, true], [path.join(F, 'sub'), false]]);
  plan = gitCommitPlan('git commit -m x', undefined);
  assert.match(plan.unknown, /working directory is unknown/);
  assert.equal(gitCommitPlan('git status && git push', M).targets.length, 0);
  assert.match(gitCommitPlan('cd ~ && git commit -m x', M, { home: F }).targets[0].cwd, /feature-repo$/);
});

test('guard asks with a reason only when rules would allow; downgrade is single use and narrow', async () => {
  const fixed = branch => async () => branch;
  // Rules allow `git -C x commit`: the guard itself must ask on main.
  let result = await checkCommitBranches(`git -C ${M} commit -m x`, F, RULES, { branchAt: fixed('main') });
  assert.equal(result.reasons.length, 1); assert.match(result.reasons[0], /protected branch main/);
  // Static gated ask on main: no extra guard ask (native asks), nothing verified.
  result = await checkCommitBranches('git commit -m x', M, RULES, { branchAt: fixed('main') });
  assert.deepEqual(result, { reasons: [], verified: 0 });
  result = await checkCommitBranches('git add . && git commit -m x', F, RULES, { branchAt: fixed('feat/x') });
  assert.deepEqual(result, { reasons: [], verified: 2 });
  // One protected target spoils the whole call.
  result = await checkCommitBranches(`git add . && git -C ${M} commit -m x`, F, RULES, { branchAt: async cwd => cwd === M ? 'main' : 'feat/x' });
  assert.equal(result.verified, 0); assert.equal(result.reasons.length, 1);
  // Without rules (lookup failed) the guard still asks on main.
  result = await checkCommitBranches('git commit -m x', M, [], { branchAt: fixed('MAIN') });
  assert.equal(result.reasons.length, 1);
  // An unknown call id or a guarded request is never downgraded.
  const event = { action: 'shell', sessionID: 's', source: { id: 'nope' }, resources: ['git commit -m x'], effect: 'ask' };
  assert.equal(downgradeVerifiedCommit(event), false); assert.equal(event.effect, 'ask');
});

test('guarded requests are never downgraded and a call is downgraded at most once', async () => {
  const hooks = {}, evaluateHooks = [];
  const ctx = {
    location: { directory: F },
    tool: { hook: async (name, callback) => { hooks[name] = callback; } },
    agent: { list: async () => ({ data: [{ id: 'b', permissions: RULES }] }) },
    permission: { hook: async (name, callback) => { evaluateHooks.push(callback); }, assert: async () => {} },
  };
  await installShellGuard(ctx);
  await hooks['execute.before']({ tool: 'shell', sessionID: 's2', agent: 'b', messageID: 'm', id: 'c1', input: { command: 'git commit -m x' } });
  const guarded = { action: 'shell', sessionID: 's2', source: { id: 'c1' }, resources: ['git commit -m x'], effect: 'ask', metadata: { [markers.GUARD_MARKER]: 'x' } };
  await evaluateHooks[0](guarded); assert.equal(guarded.effect, 'ask');
  // More gated resources than verified segments (parser disagreement) keeps the ask.
  const extra = { action: 'shell', sessionID: 's2', source: { id: 'c1' }, resources: ['git commit -m x', 'git add .'], effect: 'ask' };
  await evaluateHooks[0](extra); assert.equal(extra.effect, 'ask');
  const again = { action: 'shell', sessionID: 's2', source: { id: 'c1' }, resources: ['git commit -m x'], effect: 'ask' };
  await evaluateHooks[0](again); assert.equal(again.effect, 'ask', 'entry is single use');
  // The workdir input is honored.
  await hooks['execute.before']({ tool: 'shell', sessionID: 's2', agent: 'b', messageID: 'm', id: 'c2', input: { command: 'git commit -m x', workdir: M } });
  const onMain = { action: 'shell', sessionID: 's2', source: { id: 'c2' }, resources: ['git commit -m x'], effect: 'ask' };
  await evaluateHooks[0](onMain); assert.equal(onMain.effect, 'ask');
  // Deny is never touched.
  await hooks['execute.before']({ tool: 'shell', sessionID: 's2', agent: 'b', messageID: 'm', id: 'c3', input: { command: 'git commit -m x' } });
  const denied = { action: 'shell', sessionID: 's2', source: { id: 'c3' }, resources: ['git commit -m x'], effect: 'deny' };
  await evaluateHooks[0](denied); assert.equal(denied.effect, 'deny');
});

test('rules: gated patterns ask natively, amend and branch delete win over them', () => {
  const effect = command => explicitShellEffect(command, RULES);
  assert.equal(effect('git commit -m x').pattern, 'git commit*');
  assert.equal(effect('git add -A').pattern, 'git add*');
  assert.equal(effect('git commit --amend').pattern, 'git commit *--am*');
  assert.equal(effect('git branch -d x').effect, 'ask');
  assert.equal(effect('timeout 9 git commit -m x').effect, 'ask');
  assert.equal(analyzeShellCommand(`git -C ${F} reset --hard`, RULES).action, 'ask');
});
